const mongoose = require("mongoose");

// A quiz is generated by AI, stored with the correct answers (never sent to the browser until submitted),
// and then graded on the server so the score cannot be faked.
const questionSchema = new mongoose.Schema(
  {
    question: String,
    options: [String],
    answerIndex: Number,
    explanation: String,
  },
  { _id: false }
);

const quizSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },
    subject: { type: mongoose.Schema.Types.ObjectId, ref: "Subject", required: true },
    subjectName: String,
    topicId: { type: mongoose.Schema.Types.ObjectId, default: null },
    topicTitle: { type: String, default: "" }, // empty = whole-subject quiz
    questions: [questionSchema],
    answers: { type: [Number], default: [] },
    score: { type: Number, default: 0 },
    total: { type: Number, default: 0 },
    status: { type: String, enum: ["pending", "submitted"], default: "pending" },
    submittedAt: { type: Date, default: null },
  },
  { timestamps: true }
);

module.exports = mongoose.model("Quiz", quizSchema);
